  method: "POST",
  headers: {
    "Authorization": "Bearer {{API_KEY}}",
    "Content-Type": "application/json",
  },
  body: JSON.stringify({ model: "{{MODEL}}", prompt: "AIServeWeave 是一个分布式推理平台" }),
});
const body = await resp.json();
if (!resp.ok) throw new Error(typeof body.error === "string" ? body.error : body.error.message);
console.log(body.embedding.length);

